com.mirth.connect.plugins.javascriptstep.script:
var rawMessage = connectorMessage.getRawData();

var MessageDigest =
    Packages.java.security.MessageDigest;

var StandardCharsets =
    Packages.java.nio.charset.StandardCharsets;

var digest =
    MessageDigest.getInstance("SHA-256");

var hashBytes = digest.digest(
    new java.lang.String(rawMessage)
        .getBytes(StandardCharsets.UTF_8)
);

var hex = new java.lang.StringBuilder();

for (var i = 0; i < hashBytes.length; i++) {
    var value = hashBytes[i] & 0xff;

    if (value < 16) {
        hex.append("0");
    }

    hex.append(
        java.lang.Integer.toHexString(value)
    );
}

channelMap.put(
    "audit_payload_sha256",
    hex.toString()
);

/*
 * ORM_O01_IN interface contract validation
 *
 * HL7 ORM^O01 General Order Message used by this lab
 * as a radiology / imaging order.
 *
 * The lab contract explicitly treats OBR-3 / ORC-3 as
 * the radiology accession that will later correlate to
 * DICOM AccessionNumber. That mapping is a lab interface
 * contract, not a universal vendor/site rule.
 */

var failures = [];

function valueOf(node) {
    try {
        if (node == null) {
            return "";
        }

        return String(node.toString()).trim();
    }
    catch (e) {
        return "";
    }
}

function isValidHl7Timestamp(value) {
    if (!value) {
        return false;
    }

    var formats = [];

    if (/^\d{14}[+-]\d{4}$/.test(value)) {
        formats.push("yyyyMMddHHmmssZ");
    }

    if (/^\d{14}$/.test(value)) {
        formats.push("yyyyMMddHHmmss");
    }

    if (/^\d{12}$/.test(value)) {
        formats.push("yyyyMMddHHmm");
    }

    if (/^\d{8}$/.test(value)) {
        formats.push("yyyyMMdd");
    }

    for (var i = 0; i < formats.length; i++) {
        try {
            var parser =
                new Packages.java.text.SimpleDateFormat(
                    formats[i]
                );

            parser.setLenient(false);
            parser.parse(value);

            return true;
        }
        catch (e) {
            // Try the next accepted HL7 timestamp form.
        }
    }

    return false;
}


/* ---------------------------------------------------------
 * MESSAGE
 * --------------------------------------------------------- */

var messageCode =
    valueOf(msg['MSH']['MSH.9']['MSH.9.1']);

var triggerEvent =
    valueOf(msg['MSH']['MSH.9']['MSH.9.2']);

var messageStructure =
    valueOf(msg['MSH']['MSH.9']['MSH.9.3']);

var messageControlId =
    valueOf(msg['MSH']['MSH.10']['MSH.10.1']);

var hl7Version =
    valueOf(msg['MSH']['MSH.12']['MSH.12.1']);

var receivingApplication =
    valueOf(msg['MSH']['MSH.5']['MSH.5.1']);

var messageDateTime =
    valueOf(msg['MSH']['MSH.7']['MSH.7.1']);


/* ---------------------------------------------------------
 * PATIENT / ENCOUNTER
 * --------------------------------------------------------- */

var patientId =
    valueOf(msg['PID']['PID.3']['PID.3.1']);

var assigningAuthority =
    valueOf(msg['PID']['PID.3']['PID.3.4']);

var identifierType =
    valueOf(msg['PID']['PID.3']['PID.3.5']);

var familyName =
    valueOf(msg['PID']['PID.5']['PID.5.1']);

var givenName =
    valueOf(msg['PID']['PID.5']['PID.5.2']);

var nameType =
    valueOf(msg['PID']['PID.5']['PID.5.7']);

var dateOfBirth =
    valueOf(msg['PID']['PID.7']['PID.7.1']);

var administrativeSex =
    valueOf(msg['PID']['PID.8']['PID.8.1']);

var patientClass =
    valueOf(msg['PV1']['PV1.2']['PV1.2.1']);

var visitNumber =
    valueOf(msg['PV1']['PV1.19']['PV1.19.1']);


/* ---------------------------------------------------------
 * ORDER CONTROL — ORC
 * --------------------------------------------------------- */

var orderControl =
    valueOf(msg['ORC']['ORC.1']['ORC.1.1']);

var orcPlacerOrder =
    valueOf(msg['ORC']['ORC.2']['ORC.2.1']);

var orcFillerOrder =
    valueOf(msg['ORC']['ORC.3']['ORC.3.1']);

var orderStatus =
    valueOf(msg['ORC']['ORC.5']['ORC.5.1']);

var orderDateTime =
    valueOf(msg['ORC']['ORC.9']['ORC.9.1']);

var orderingProviderId =
    valueOf(msg['ORC']['ORC.12']['ORC.12.1']);

var orderingProviderFamily =
    valueOf(msg['ORC']['ORC.12']['ORC.12.2']);

var orderingProviderGiven =
    valueOf(msg['ORC']['ORC.12']['ORC.12.3']);


/* ---------------------------------------------------------
 * OBSERVATION REQUEST — OBR
 *
 * For this imaging-order interface, OBR-3 is the
 * radiology accession identifier.
 * --------------------------------------------------------- */

var obrPlacerOrder =
    valueOf(msg['OBR']['OBR.2']['OBR.2.1']);

var obrFillerOrder =
    valueOf(msg['OBR']['OBR.3']['OBR.3.1']);

var accessionNumber =
    obrFillerOrder;

var procedureCode =
    valueOf(msg['OBR']['OBR.4']['OBR.4.1']);

var procedureText =
    valueOf(msg['OBR']['OBR.4']['OBR.4.2']);

var procedureCodingSystem =
    valueOf(msg['OBR']['OBR.4']['OBR.4.3']);


/* ---------------------------------------------------------
 * VALIDATION
 * --------------------------------------------------------- */

if (!patientId) {
    failures.push("Patient ID present");
}

if (!assigningAuthority) {
    failures.push("Assigning authority present");
}

if (identifierType != "MR") {
    failures.push("Identifier type is MR");
}

if (!familyName) {
    failures.push("Family name present");
}

if (!givenName) {
    failures.push("Given name present");
}

if (nameType != "L") {
    failures.push("Patient name type recognized");
}

if (!/^\d{8}$/.test(dateOfBirth)) {
    failures.push("DOB format is YYYYMMDD");
}

if (
    administrativeSex != "M" &&
    administrativeSex != "F" &&
    administrativeSex != "O" &&
    administrativeSex != "U"
) {
    failures.push("Administrative sex recognized");
}

if (
    patientClass != "I" &&
    patientClass != "O" &&
    patientClass != "E"
) {
    failures.push("Patient class recognized");
}

if (!visitNumber) {
    failures.push("Visit number present");
}

if (messageCode != "ORM") {
    failures.push("Message type is ORM");
}

if (triggerEvent != "O01") {
    failures.push("Trigger event is O01");
}

if (messageStructure != "ORM_O01") {
    failures.push("Message structure is ORM_O01");
}

if (!messageControlId) {
    failures.push("Message control ID present");
}

if (hl7Version != "2.5.1") {
    failures.push("HL7 version is 2.5.1");
}

if (receivingApplication != "MIRTH") {
    failures.push("Receiving application is MIRTH");
}

if (!isValidHl7Timestamp(messageDateTime)) {
    failures.push("MSH-7 timestamp valid");
}

if (orderControl != "NW") {
    failures.push("Order control is NW");
}

if (!orcPlacerOrder) {
    failures.push("ORC placer order number present");
}

if (!orcFillerOrder) {
    failures.push("ORC filler order number present");
}

if (
    orderStatus != "SC" &&
    orderStatus != "IP" &&
    orderStatus != "CM" &&
    orderStatus != "CA" &&
    orderStatus != "DC" &&
    orderStatus != "ER" &&
    orderStatus != "HD" &&
    orderStatus != "RP"
) {
    failures.push("Order status recognized");
}

if (!isValidHl7Timestamp(orderDateTime)) {
    failures.push("ORC transaction timestamp valid");
}

if (!orderingProviderId) {
    failures.push("Ordering provider ID present");
}

if (!orderingProviderFamily) {
    failures.push("Ordering provider family name present");
}

if (!orderingProviderGiven) {
    failures.push("Ordering provider given name present");
}

if (!obrPlacerOrder) {
    failures.push("OBR placer order number present");
}

if (!obrFillerOrder) {
    failures.push("OBR filler order number present");
}

if (orcPlacerOrder != obrPlacerOrder) {
    failures.push(
        "ORC and OBR placer order numbers agree"
    );
}

if (orcFillerOrder != obrFillerOrder) {
    failures.push(
        "ORC and OBR filler order numbers agree"
    );
}

if (!procedureCode) {
    failures.push("Procedure code present");
}

if (!procedureText) {
    failures.push("Procedure description present");
}

if (!procedureCodingSystem) {
    failures.push("Procedure coding system present");
}

if (!accessionNumber) {
    failures.push("Accession number present");
}


/* ---------------------------------------------------------
 * BUSINESS CONTEXT
 *
 * These values will be consumed by the PostgreSQL
 * destination when audit.orm_orders is persisted.
 * --------------------------------------------------------- */

channelMap.put(
    "orm_assigning_authority",
    assigningAuthority
);

channelMap.put(
    "orm_identifier_type",
    identifierType
);

channelMap.put(
    "orm_visit_number",
    visitNumber
);

channelMap.put(
    "orm_order_control",
    orderControl
);

channelMap.put(
    "orm_placer_order_number",
    orcPlacerOrder
);

channelMap.put(
    "orm_filler_order_number",
    orcFillerOrder
);

channelMap.put(
    "orm_accession_number",
    accessionNumber
);

channelMap.put(
    "orm_order_status",
    orderStatus
);

channelMap.put(
    "orm_procedure_code",
    procedureCode
);

channelMap.put(
    "orm_procedure_text",
    procedureText
);

channelMap.put(
    "orm_procedure_coding_system",
    procedureCodingSystem
);

channelMap.put(
    "orm_ordering_provider_id",
    orderingProviderId
);

channelMap.put(
    "orm_ordering_provider_family",
    orderingProviderFamily
);

channelMap.put(
    "orm_ordering_provider_given",
    orderingProviderGiven
);

channelMap.put(
    "orm_order_datetime_raw",
    orderDateTime
);


/* ---------------------------------------------------------
 * VALIDATION RESULT
 * --------------------------------------------------------- */

var validationStatus =
    failures.length == 0
        ? "PASS"
        : "FAIL";

var failureReason =
    failures.join(" | ");

channelMap.put(
    "validation_status",
    validationStatus
);

channelMap.put(
    "validation_failure_category",
    failures.length == 0
        ? ""
        : "VALIDATION_ERROR"
);

channelMap.put(
    "validation_failure_reason",
    failureReason
);

logger.info(
    "ORM imaging-order validation: status=" +
    validationStatus +
    ", control_id=" +
    messageControlId +
    ", patient_id=" +
    patientId +
    ", placer_order=" +
    orcPlacerOrder +
    ", accession=" +
    accessionNumber +
    ", failed_rule_count=" +
    failures.length +
    (
        failures.length > 0
            ? ", failed_rules=" + failureReason
            : ""
    )
);

properties.query:
var dbConn = null;

try {
    /*
     * Obtain interoperability database configuration from
     * the Mirth container environment.
     */
    var dbUrl = java.lang.System.getenv("INTEROP_DB_URL");
    var dbUser = java.lang.System.getenv("INTEROP_DB_USER");
    var dbPassword = java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (dbUrl == null || dbUser == null || dbPassword == null) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }


    /*
     * Open the interoperability audit database connection.
     */
    dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        "org.postgresql.Driver",
        dbUrl,
        dbUser,
        dbPassword
    );


    /*
     * PostgreSQL remains authoritative for transaction
     * classification.
     *
     * The function will return:
     *
     *   recorded_audit_id
     *   logical_transaction_id
     *   classified_outcome
     *
     * classified_outcome will be one of:
     *
     *   FIRST_DELIVERY
     *   EXACT_REPLAY
     *   CONFLICTING_REUSE
     */
    var sql =
        "SELECT " +
        "recorded_audit_id, " +
        "logical_transaction_id, " +
        "classified_outcome " +
        "FROM audit.record_interface_receipt(" +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR), " +
        "CAST(? AS VARCHAR)" +
        ")";


    /*
     * Bind the values rather than concatenating HL7 content
     * directly into the SQL statement.
     */
    var parameters = new java.util.ArrayList();

    parameters.add(
        channelMap.get("audit_message_control_id")
    );

    parameters.add(
        channelMap.get("audit_message_type")
    );

    parameters.add(
        channelMap.get("audit_trigger_event")
    );

    parameters.add(
        channelMap.get("audit_patient_identifier")
    );

    parameters.add(
        channelMap.get("audit_sending_application")
    );

    parameters.add(
        channelMap.get("audit_sending_facility")
    );

    parameters.add(
        channelMap.get("audit_payload_sha256")
    );


    /*
     * Execute PostgreSQL's classifier and capture its
     * returned row.
     */
    var result = dbConn.executeCachedQuery(
        sql,
        parameters
    );


    if (!result.next()) {
        throw new Error(
            "record_interface_receipt returned no classification result."
        );
    }


    var recordedAuditId =
        result.getString("recorded_audit_id");

    var logicalTransactionId =
        result.getString("logical_transaction_id");

    var classifiedOutcome =
        result.getString("classified_outcome");


    if (classifiedOutcome == null) {
        throw new Error(
            "record_interface_receipt returned a null classification."
        );
    }


    /*
     * Make PostgreSQL's authoritative result available
     * to the remainder of this Mirth message lifecycle.
     */
    channelMap.put(
        "audit_recorded_audit_id",
        java.lang.String.valueOf(recordedAuditId)
    );

    channelMap.put(
        "audit_logical_transaction_id",
        java.lang.String.valueOf(logicalTransactionId)
    );

    channelMap.put(
        "audit_attempt_outcome",
        classifiedOutcome
    );


    /*
     * Temporary validation logging.
     *
     * No database password is logged.
     */
    logger.info(
        "HL7 audit classification: outcome=" +
        classifiedOutcome +
        ", transaction_id=" +
        logicalTransactionId +
        ", audit_id=" +
        recordedAuditId
    );

}
finally {
    if (dbConn != null) {
        dbConn.close();
    }
}

/*
 * ORM_O01_IN
 * Persist canonical imaging-order business state.
 *
 * Destination 1 has already performed authoritative
 * transaction classification through:
 *
 *     audit.record_interface_receipt
 *
 * This destination therefore consumes:
 *
 *     FIRST_DELIVERY
 *     EXACT_REPLAY
 *     CONFLICTING_REUSE
 *
 * Only FIRST_DELIVERY and EXACT_REPLAY may establish
 * the canonical audit.orm_orders business row.
 */

var dbConn = null;

try {

    var validationStatus =
        String(
            channelMap.get(
                "validation_status"
            )
        );

    if (validationStatus != "PASS") {
        return;
    }


    var auditOutcome =
        String(
            channelMap.get(
                "audit_attempt_outcome"
            )
        );


    /*
     * A conflicting reuse is deliberately prevented from
     * changing canonical imaging-order business state.
     */

    if (auditOutcome == "CONFLICTING_REUSE") {

        logger.info(
            "ORM order persistence skipped: " +
            "outcome=CONFLICTING_REUSE, control_id=" +
            channelMap.get(
                "audit_message_control_id"
            )
        );

        return;
    }


    if (
        auditOutcome != "FIRST_DELIVERY" &&
        auditOutcome != "EXACT_REPLAY"
    ) {
        throw new Error(
            "Unexpected ORM transaction classification: " +
            auditOutcome
        );
    }


    var transactionId =
        String(
            channelMap.get(
                "audit_logical_transaction_id"
            )
        );

    if (
        transactionId == null ||
        transactionId == "" ||
        transactionId == "null"
    ) {
        throw new Error(
            "ORM logical transaction ID is missing."
        );
    }


    var dbUrl =
        java.lang.System.getenv(
            "INTEROP_DB_URL"
        );

    var dbUser =
        java.lang.System.getenv(
            "INTEROP_DB_USER"
        );

    var dbPassword =
        java.lang.System.getenv(
            "INTEROP_DB_PASSWORD"
        );

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }


    dbConn =
        DatabaseConnectionFactory
            .createDatabaseConnection(
                "org.postgresql.Driver",
                dbUrl,
                dbUser,
                dbPassword
            );


    /*
     * transaction_id is UNIQUE in audit.orm_orders.
     *
     * ON CONFLICT DO NOTHING makes persistence idempotent:
     * an exact replay cannot create a duplicate business row.
     *
     * It also supports recovery from a partial failure:
     * if the generic receipt was committed but ORM business
     * persistence failed, a later EXACT_REPLAY may establish
     * the previously missing business row.
     */

    var insertSql =
        "INSERT INTO audit.orm_orders (" +
        "transaction_id, " +
        "message_control_id, " +
        "patient_identifier, " +
        "assigning_authority, " +
        "identifier_type, " +
        "visit_number, " +
        "order_control, " +
        "placer_order_number, " +
        "filler_order_number, " +
        "accession_number, " +
        "order_status, " +
        "procedure_code, " +
        "procedure_text, " +
        "procedure_coding_system, " +
        "ordering_provider_id, " +
        "ordering_provider_family, " +
        "ordering_provider_given, " +
        "order_datetime_raw" +
        ") VALUES (" +
        "CAST(? AS BIGINT), " +
        "?, ?, ?, ?, ?, ?, ?, ?, ?, " +
        "?, ?, ?, ?, ?, ?, ?, ?" +
        ") " +
        "ON CONFLICT (transaction_id) DO NOTHING";


    var parameters =
        new java.util.ArrayList();

    parameters.add(transactionId);

    parameters.add(
        channelMap.get(
            "audit_message_control_id"
        )
    );

    parameters.add(
        channelMap.get(
            "audit_patient_identifier"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_assigning_authority"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_identifier_type"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_visit_number"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_order_control"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_placer_order_number"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_filler_order_number"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_accession_number"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_order_status"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_procedure_code"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_procedure_text"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_procedure_coding_system"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_ordering_provider_id"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_ordering_provider_family"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_ordering_provider_given"
        )
    );

    parameters.add(
        channelMap.get(
            "orm_order_datetime_raw"
        )
    );


    var rowsAffected =
        dbConn.executeUpdate(
            insertSql,
            parameters
        );


    /*
     * Do not merely assume that ON CONFLICT means the
     * existing business row is correct.
     *
     * Re-read canonical state and verify the critical
     * order identity. A mismatch here represents an
     * internal integrity failure and must fail closed.
     */

    var verifySql =
        "SELECT " +
        "message_control_id, " +
        "patient_identifier, " +
        "placer_order_number, " +
        "filler_order_number, " +
        "accession_number, " +
        "procedure_code " +
        "FROM audit.orm_orders " +
        "WHERE transaction_id = CAST(? AS BIGINT)";


    var verifyParameters =
        new java.util.ArrayList();

    verifyParameters.add(
        transactionId
    );


    var result =
        dbConn.executeCachedQuery(
            verifySql,
            verifyParameters
        );


    if (!result.next()) {
        throw new Error(
            "Canonical ORM order row was not found after persistence."
        );
    }


    function requireEqual(
        databaseValue,
        expectedValue,
        fieldName
    ) {

        var actual =
            databaseValue == null
                ? ""
                : String(databaseValue);

        var expected =
            expectedValue == null
                ? ""
                : String(expectedValue);

        if (actual != expected) {
            throw new Error(
                "Canonical ORM order integrity mismatch for " +
                fieldName +
                ": database=" +
                actual +
                ", expected=" +
                expected
            );
        }
    }


    requireEqual(
        result.getString(
            "message_control_id"
        ),
        channelMap.get(
            "audit_message_control_id"
        ),
        "message_control_id"
    );

    requireEqual(
        result.getString(
            "patient_identifier"
        ),
        channelMap.get(
            "audit_patient_identifier"
        ),
        "patient_identifier"
    );

    requireEqual(
        result.getString(
            "placer_order_number"
        ),
        channelMap.get(
            "orm_placer_order_number"
        ),
        "placer_order_number"
    );

    requireEqual(
        result.getString(
            "filler_order_number"
        ),
        channelMap.get(
            "orm_filler_order_number"
        ),
        "filler_order_number"
    );

    requireEqual(
        result.getString(
            "accession_number"
        ),
        channelMap.get(
            "orm_accession_number"
        ),
        "accession_number"
    );

    requireEqual(
        result.getString(
            "procedure_code"
        ),
        channelMap.get(
            "orm_procedure_code"
        ),
        "procedure_code"
    );


    logger.info(
        "ORM order persistence: outcome=" +
        auditOutcome +
        ", transaction_id=" +
        transactionId +
        ", rows_inserted=" +
        rowsAffected +
        ", placer_order=" +
        channelMap.get(
            "orm_placer_order_number"
        ) +
        ", accession=" +
        channelMap.get(
            "orm_accession_number"
        )
    );

}
finally {

    if (dbConn != null) {
        dbConn.close();
    }
}

var dbConn = null;

try {
    /*
     * Obtain interoperability database configuration
     * from the Mirth container environment.
     */
    var dbUrl =
        java.lang.System.getenv("INTEROP_DB_URL");

    var dbUser =
        java.lang.System.getenv("INTEROP_DB_USER");

    var dbPassword =
        java.lang.System.getenv("INTEROP_DB_PASSWORD");

    if (
        dbUrl == null ||
        dbUser == null ||
        dbPassword == null
    ) {
        throw new Error(
            "Required INTEROP_DB_* environment configuration is missing."
        );
    }

    /*
     * Open interoperability audit database connection.
     */
    dbConn =
        DatabaseConnectionFactory.createDatabaseConnection(
            "org.postgresql.Driver",
            dbUrl,
            dbUser,
            dbPassword
        );

    /*
     * Persist rejected message as durable quarantine evidence.
     *
     * quarantine_status is not supplied here because PostgreSQL
     * assigns the default value QUARANTINED.
     */
    var sql =
        "INSERT INTO audit.quarantined_messages (" +
        "message_control_id, " +
        "message_type, " +
        "trigger_event, " +
        "patient_identifier, " +
        "sending_application, " +
        "sending_facility, " +
        "failure_category, " +
        "failure_reason, " +
        "payload_text, " +
        "payload_sha256" +
        ") VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

    var parameters =
        new java.util.ArrayList();

    parameters.add(
        channelMap.get("audit_message_control_id")
    );

    parameters.add(
        channelMap.get("audit_message_type")
    );

    parameters.add(
        channelMap.get("audit_trigger_event")
    );

    parameters.add(
        channelMap.get("audit_patient_identifier")
    );

    parameters.add(
        channelMap.get("audit_sending_application")
    );

    parameters.add(
        channelMap.get("audit_sending_facility")
    );

    parameters.add(
        channelMap.get("validation_failure_category")
    );

    parameters.add(
        channelMap.get("validation_failure_reason")
    );

    parameters.add(
        connectorMessage.getRawData()
    );

    parameters.add(
        channelMap.get("audit_payload_sha256")
    );

    dbConn.executeUpdate(
        sql,
        parameters
    );

    logger.info(
        "ADT quarantine persistence: " +
        "control_id=" +
        channelMap.get("audit_message_control_id") +
        ", category=" +
        channelMap.get("validation_failure_category") +
        ", status=QUARANTINED"
    );
}
catch (e) {
    logger.error(
        "ADT quarantine persistence failed: " +
        e
    );

    /*
     * Fail closed.
     *
     * If we cannot preserve the rejected transaction,
     * we cannot claim that it was safely contained.
     */
    throw e;
}
finally {
    if (dbConn != null) {
        dbConn.close();
    }
}

channel.postprocessingScript:
/*
 * ORM_O01_IN postprocessor
 *
 * Translate validation state and authoritative transaction
 * classification into the application-level HL7 acknowledgment
 * returned to the sender.
 *
 * Policy:
 *
 * validation failure    -> AR
 * FIRST_DELIVERY        -> AA
 * EXACT_REPLAY          -> AA
 * CONFLICTING_REUSE     -> AR
 * destination failure   -> AE
 * unknown condition     -> AE
 */

var auditOutcome =
    channelMap.get("audit_attempt_outcome");

var validationStatus =
    channelMap.get("validation_status");

var validationFailureReason =
    channelMap.get("validation_failure_reason");


/*
 * Inspect destination connector status independently of
 * validation and transaction classification.
 *
 * This preserves important distinctions:
 *
 *     validation-policy rejection -> AR
 *     integrity-policy rejection  -> AR
 *     processing/infrastructure failure -> AE
 */

var connectorMessages =
    message.getConnectorMessages();

var destinationError = false;

var connectorIterator =
    connectorMessages.entrySet().iterator();

while (connectorIterator.hasNext()) {

    var connectorEntry =
        connectorIterator.next();

    var metadataId =
        String(connectorEntry.getKey());

    /*
     * Metadata ID 0 is the source connector.
     * Everything else is a destination.
     */
    if (metadataId != "0") {

        var destinationStatus =
            String(
                connectorEntry
                    .getValue()
                    .getStatus()
            );

        if (destinationStatus == "ERROR") {
            destinationError = true;
            break;
        }
    }
}


/*
 * Obtain the original HL7 message from the source connector.
 *
 * The postprocessor's "message" object represents the complete
 * processed Mirth message. Connector metadata ID 0 is the source.
 */

var sourceConnectorMessage =
    connectorMessages.get(0);

var rawMessage =
    String(
        sourceConnectorMessage.getRawData()
    );


/*
 * Locate and parse the original MSH segment.
 */

var rawSegments =
    rawMessage.split(/\r\n|\n|\r/);

var mshSegment = null;

for (var i = 0; i < rawSegments.length; i++) {

    if (rawSegments[i].indexOf("MSH|") == 0) {
        mshSegment = rawSegments[i];
        break;
    }
}


var mshFields =
    mshSegment != null
        ? mshSegment.split("|")
        : [];


/*
 * Original MSH positions after JavaScript split("|"):
 *
 * [0]  MSH
 * [1]  MSH-2 Encoding Characters
 * [2]  MSH-3 Sending Application
 * [3]  MSH-4 Sending Facility
 * [4]  MSH-5 Receiving Application
 * [5]  MSH-6 Receiving Facility
 * [6]  MSH-7 Message Date/Time
 * [8]  MSH-9 Message Type
 * [9]  MSH-10 Message Control ID
 * [10] MSH-11 Processing ID
 * [11] MSH-12 Version ID
 */

var encodingCharacters =
    mshFields.length > 1 &&
    mshFields[1]
        ? mshFields[1]
        : "^~\\&";


var originalSendingApplication =
    mshFields.length > 2 &&
    mshFields[2]
        ? mshFields[2]
        : String(
            channelMap.get(
                "audit_sending_application"
            )
        );


var originalSendingFacility =
    mshFields.length > 3 &&
    mshFields[3]
        ? mshFields[3]
        : String(
            channelMap.get(
                "audit_sending_facility"
            )
        );


var originalReceivingApplication =
    mshFields.length > 4 &&
    mshFields[4]
        ? mshFields[4]
        : "MIRTH";


var originalReceivingFacility =
    mshFields.length > 5 &&
    mshFields[5]
        ? mshFields[5]
        : "INTEROPLAB";


var originalControlId =
    mshFields.length > 9 &&
    mshFields[9]
        ? mshFields[9]
        : String(
            channelMap.get(
                "audit_message_control_id"
            )
        );


var processingId =
    mshFields.length > 10 &&
    mshFields[10]
        ? mshFields[10]
        : "P";


var versionId =
    mshFields.length > 11 &&
    mshFields[11]
        ? mshFields[11]
        : "2.5.1";


var triggerEvent =
    String(
        channelMap.get(
            "audit_trigger_event"
        )
    );


/*
 * Determine the application acknowledgment code.
 */

var ackCode;
var ackText;


/*
 * Validation failure takes precedence over transaction
 * classification because invalid messages do not enter the
 * normal transaction-classification path.
 */
if (validationStatus == "FAIL") {

    ackCode = "AR";

    ackText =
        "Message rejected: " +
        (
            validationFailureReason
                ? String(validationFailureReason)
                : "interface contract validation failed."
        );

}
else if (destinationError) {

    ackCode = "AE";

    ackText =
        "Message processing error.";

}
else if (auditOutcome == "FIRST_DELIVERY") {

    ackCode = "AA";

    ackText =
        "Message accepted.";

}
else if (auditOutcome == "EXACT_REPLAY") {

    ackCode = "AA";

    ackText =
        "Exact replay accepted.";

}
else if (auditOutcome == "CONFLICTING_REUSE") {

    ackCode = "AR";

    ackText =
        "Message rejected: conflicting message identity reuse.";

}
else {

    /*
     * Fail closed if validation/classification state is missing
     * or contains an unexpected value.
     */

    ackCode = "AE";

    ackText =
        "Unable to determine transaction classification.";
}


/*
 * The ACK itself needs its own MSH-10.
 *
 * It must not reuse the incoming message's MSH-10.
 */

var ackUuid =
    String(
        java.util.UUID.randomUUID()
    )
    .replace(/-/g, "")
    .substring(0, 16);

var ackControlId =
    "ACK" + ackUuid;


var timestamp =
    new java.text.SimpleDateFormat(
        "yyyyMMddHHmmss.SSS"
    ).format(
        new java.util.Date()
    );


/*
 * For an ADT^A04 the general acknowledgment message type is:
 *
 *     ACK^A04^ACK
 *
 * Swap original sender/receiver application and facility
 * values when constructing the response MSH.
 */

var ack =
    "MSH|" +
    encodingCharacters +
    "|" +
    originalReceivingApplication +
    "|" +
    originalReceivingFacility +
    "|" +
    originalSendingApplication +
    "|" +
    originalSendingFacility +
    "|" +
    timestamp +
    "||" +
    "ACK^" +
    triggerEvent +
    "^ACK|" +
    ackControlId +
    "|" +
    processingId +
    "|" +
    versionId +
    "\r" +

    "MSA|" +
    ackCode +
    "|" +
    originalControlId +
    "|" +
    ackText +
    "\r";


logger.info(
    "HL7 postprocessor ACK policy: " +
    "validation_status=" +
    validationStatus +
    ", outcome=" +
    auditOutcome +
    ", destination_error=" +
    destinationError +
    ", ack_code=" +
    ackCode +
    ", original_control_id=" +
    originalControlId
);


/*
 * Returning a String causes Mirth to store this response
 * under the Postprocessor response-map entry.
 */

return ack;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
